"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[2719],{9703(e){e.exports=JSON.parse('{"title":"\ub2f9\uc2e0\uc774 Remix\ub97c \uc0ac\uc6a9\ud574\uc57c \ud558\ub294 \uc774\uc720","date":"2024-09-21","coverUrl":null,"html":"<h2 data-notion-block-id=\\"4a3e686e-6b9d-4ff1-99e8-65ffca0cb84e\\" id=\\"4a3e686e-6b9d-4ff1-99e8-65ffca0cb84e\\">\ub2f9\uc2e0\uc774 Remix\ub97c \uc0ac\uc6a9\ud574\uc57c \ud558\ub294 \uc774\uc720(\uc5b4\uadf8\ub85c \ub044\ub294 \uc720\ud29c\ube0c \ud1a4\uc73c\ub85c)</h2><a href=\\"https://echobind.com/post/oops-i-accidentally-made-our-website-faster-by-switching-to-remix\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://echobind.com/post/oops-i-accidentally-made-our-website-faster-by-switching-to-remix</a><p data-notion-block-id=\\"9d146648-d6b7-44af-a58a-f572fecfa669\\"><b>\uc2ec\uc724\uc12d</b>: NextJS\uc5d0\uc11c Remix\ub85c \ub9c8\uc774\uadf8\ub808\uc774\uc158\ud55c \uacfc\uc815\uc744 \ub2f4\uc740 \uae00\uc785\ub2c8\ub2e4. Remix\uac00 NextJS\ubcf4\ub2e4 \ub098\uc740 \uc810\uc740 \uc6f9 \ud45c\uc900\uc5d0 \uac00\uae4c\uc6b4 API, \uc5b4\ub290 \ud55c \uc778\ud504\ub77c\uc640 \ubb34\uad00\ud558\uac8c \ub2e4\uc591\ud55c \uc5b4\ub311\ud130\ub97c \uc81c\uacf5\ud558\ub294 \uc810(NextJS\ub294 vercel\uc5d0 \uac15\ub825\ud558\uac8c \ubb36\uc5ec\uc788\uc74c), \ub2e4\uc591\ud55c \uc138\ud305 \ubc29\uc2dd\uc744 \uc81c\uacf5\ud558\ub294 \uc810\uc5d0 \uc788\uc2b5\ub2c8\ub2e4. \uc704\uc758 \ub9c8\uc774\uadf8\ub808\uc774\uc158 \uae00\uacfc ChatGPT\uc758 \ub9c8\uc774\uadf8\ub808\uc774\uc158 \uc18c\uc2dd\uc744 \ubcf4\uba74 \ub9c8\uc774\uadf8\ub808\uc774\uc158\uc744 \uc870\uac74\uc5d0 \ub9de\ub294 \uacbd\uc6b0 \uace0\ub824\ud574\ubcfc \uc218\ub3c4 \uc788\uaca0\ub124\uc694. Remix\uc5d0\uc11c <a href=\\"https://github.com/remix-run/react-router/pull/11773\\">\ucf54\ub4dc \uae30\ubc18 \ub77c\uc6b0\ud305 \uc5c5\ub370\uc774\ud2b8</a>, \ubaa8\ub4e0 JS\ud658\uacbd\uc5d0\uc11c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 <a href=\\"https://github.com/mjackson/remix-the-web/tree/main\\">\uc678\ubd80 \ud328\ud0a4\uc9c0 \uc81c\uc791</a>\ub3c4 \uc9c4\ud589\ud558\uace0 \uc788\uc73c\ub2c8 \uad00\uc2ec\uac00\uc9c0\uace0 \uc788\uc5b4\uc57c \uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"1f646e8f-3eed-4394-9662-c26ff95d1aa6\\" id=\\"1f646e8f-3eed-4394-9662-c26ff95d1aa6\\">\uc0c1\ud0dc\ub294 \ubaa8\ub450, \uc720\ud55c \uc0c1\ud0dc \uae30\uacc4\uc744 \ubcf8\ub72c \uac83</h2><a href=\\"https://massimilianomirra.com/notes/expressive-components-in-vanilla-react-part-1-type-states\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://massimilianomirra.com/notes/expressive-components-in-vanilla-react-part-1-type-states</a><p data-notion-block-id=\\"d6f8b0fb-433d-48cd-a6c6-c21cdc776fd1\\"><b>\uc2ec\uc724\uc12d</b>: \ud544\uc694\ud55c \uc0c1\ud0dc\ub97c \ubaa8\ub450 \ubd84\ub9ac\ud558\uc9c0 \uc54a\uace0 union\ud0c0\uc785\uc73c\ub85c \ud604\uc7ac \uc0c1\ud669\uacfc \ud544\uc694\ud55c \uac12\uc744 \uc815\uc758\ud558\ub294 \ubc29\uc2dd\uc744 \ub3c4\uc785\ud558\ub294 \uacfc\uc815\uc744 \uc18c\uac1c\ud55c \uae00\uc785\ub2c8\ub2e4. \uc720\ud55c \uc0c1\ud0dc \uae30\uacc4\ub77c\ub294 \uac1c\ub150\uc744 \ubc14\ub2d0\ub77c JS\ub85c \uad6c\ud604\ud558\ub294 \uacfc\uc815\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. Flux\ud328\ud134\ubcf4\ub2e4 \uc81c\ud55c\uc744 \ub450\uba70 \uc27d\uac8c \uacfc\uc815\uc744 \uc81c\uc5b4\ud560 \uc218 \uc788\ub294 \uc720\ud55c \uc0c1\ud0dc \uae30\uacc4\ub77c\ub294 \uac1c\ub150\uc744 \uc774\ud574\ud558\uace0 <a href=\\"https://stately.ai/docs/xstate\\"><code>XState</code></a><a href=\\"https://stately.ai/docs/xstate\\">\ub77c\uc774\ube0c\ub7ec\ub9ac</a>\ub97c \uc0ac\uc6a9\ud558\uba74 \uc88b\uc2b5\ub2c8\ub2e4. XState \ud29c\ud1a0\ub9ac\uc5bc\uc744 \uc6d0\ud558\uc2dc\uba74, <a href=\\"https://www.typeonce.dev/course/xstate-complete-getting-started-guide\\">\uc774 \uac00\uc774\ub4dc</a>\ub97c \ucc38\uace0\ud558\uc138\uc694.</p><h2 data-notion-block-id=\\"d7e8d6a6-e384-40d3-9106-cf4c42e2f716\\" id=\\"d7e8d6a6-e384-40d3-9106-cf4c42e2f716\\">\ub300\uccb4 \uc5b8\uc81c\ubd80\ud130 ES5\ub97c \uc4f0\uc9c0 \uc54a\uc558\ub2e4\uace0 \ucc29\uac01\ud55c\uac70\uc9c0?</h2><a href=\\"https://philipwalton.com/articles/the-state-of-es5-on-the-web/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://philipwalton.com/articles/the-state-of-es5-on-the-web/</a><p data-notion-block-id=\\"876bd4bd-80ce-4229-839b-a889497c3927\\"><b>\uc2ec\uc724\uc12d</b>: \uc6f9\uc5d0\uc11c \uc21c\uc218 ES6+ \ubb38\ubc95\uc744 \uc5bc\ub9c8\ub098 \uc0ac\uc6a9\ud558\uace0 \uc788\ub294\uc9c0\uc5d0 \ub300\ud55c \ub370\uc774\ud130, \ubc88\ub4e4\ub7ec\uc5d0\uc11c \uc81c\uacf5\ud558\ub294 \ud2b8\ub79c\uc2a4\ud30c\uc77c \uae30\ubcf8\uac12, \ub77c\uc774\ube0c\ub7ec\ub9ac\uc758 ES6+ \ubb38\ubc95\uc744 \uc0ac\uc6a9\ud558\uace0 \uc788\ub294\uc9c0\ub97c \uae30\ubc18\uc73c\ub85c ES5 \ubb38\ubc95\uc758 \uc0ac\uc6a9 \ud604\ud669\uc744 \uc54c\ub824\uc90d\ub2c8\ub2e4. \uadf8\ub9ac\uace0 \uad8c\uc7a5\uc0ac\ud56d\ub3c4\uc694. ES6+\ub97c \uc0ac\uc6a9\ud558\ub294 \uac83\uc740 \uc720\uc9c0\ubcf4\uc218\uc5d0\uc11c \uc2dc\uc791\ud574\uc11c \ud06c\uac8c\ub294 \uc131\ub2a5 \ucd5c\uc801\ud654, \ucf54\ub4dc \uad6c\uc870\uc5d0\ub3c4 \uc601\ud5a5\uc774 \uac08 \uc218 \uc788\uc73c\ub2c8 ES6+\ub97c \uc0ac\uc6a9\ud558\ub418 \ud2b8\ub79c\uc2a4\ud30c\uc77c \uacfc\uc815\uacfc \uc9c0\uc6d0 QA\uacfc\uc815\uc744 \ud655\uc778\ud574\uc57c\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"ab9dd614-7fdb-4b93-b869-2961487b813f\\" id=\\"ab9dd614-7fdb-4b93-b869-2961487b813f\\"><code>setTimeout()</code> vs <code>setImmediate()</code></h2><a href=\\"https://www.trevorlasn.com/blog/setimmediate-vs-settimeout-in-javascript\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.trevorlasn.com/blog/setimmediate-vs-settimeout-in-javascript</a><p data-notion-block-id=\\"e8556102-6d27-4b71-9edb-939650eb3677\\"><code>setTimeout()</code>\uc640 <code>setImmediate()</code>\uc758 \ucc28\uc774\ub97c \uc774\ubca4\ud2b8 \ub8e8\ud504\uc640 \ud568\uaed8 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ud0c0\uc774\ubc0d\uc744 \uc815\ud655\ud788 \uc81c\uc5b4\ud558\uae30 \uc704\ud574 \ubd10\uc57c\ud55c\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ucd94\uac00\ub85c <a href=\\"https://ones-to-watch.ethansup.net/news/post/0269c0cd-b5f8-4f29-8457-f7976befb282#6e947f37-d04f-41c5-8898-9f0ab795f62d\\">NodeJS\uc5d0\uc11c </a><a href=\\"https://ones-to-watch.ethansup.net/news/post/0269c0cd-b5f8-4f29-8457-f7976befb282#6e947f37-d04f-41c5-8898-9f0ab795f62d\\"><code>setTimeout()</code></a><a href=\\"https://ones-to-watch.ethansup.net/news/post/0269c0cd-b5f8-4f29-8457-f7976befb282#6e947f37-d04f-41c5-8898-9f0ab795f62d\\"> \ub204\uc218 \uc774\uc288</a>\ub3c4 \uc788\uc73c\ub2c8 \ud655\uc778\ud558\uace0 \uc0ac\uc6a9\ud574\uc57c \ud560 \uac83\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"4544d48e-6e85-4331-b885-b28033927767\\" id=\\"4544d48e-6e85-4331-b885-b28033927767\\"><code>:has()</code>\uc18c\uac1c, \uadf8\ub9ac\uace0 \uc0ac\uc6a9\ucc98</h2><a href=\\"https://www.joshwcomeau.com/css/has/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.joshwcomeau.com/css/has/</a><a href=\\"https://www.developerway.com/posts/replacing-react-with-css\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.developerway.com/posts/replacing-react-with-css</a><p data-notion-block-id=\\"f14277a1-35f8-4f5b-92fe-8c6bdb5afb01\\"><b>\uc2ec\uc724\uc12d</b>: <code>:has()</code>\ub294 \ucd5c\uadfc\uc5d0 \ucd94\uac00\ub41c \uc720\uc6a9\ud55c \uc758\uc0ac \ud074\ub798\uc2a4 \uc911 \ud558\ub098\uc785\ub2c8\ub2e4. \ub450 \uae00\uc740 \uc5b4\ub514\uc5d0 \uc0ac\uc6a9\ub418\uba74 \uc88b\uc740\uc9c0 \ucf54\ub4dc\uc640 \ud568\uaed8 \uc18c\uac1c\ud569\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \ube44\uad50\uc801 \ucd5c\uadfc\uc5d0 \ucd94\uac00\ub418\uc5c8\uc73c\ubbc0\ub85c \uc774\uc804 \ubc84\uc804\uc5d0 \ub300\ud55c \uc9c0\uc6d0\uc774 \ud544\uc694\ud55c \uacbd\uc6b0 \ub354 \uc2e0\uc911\ud558\uac8c \uc0ac\uc6a9\ud574\uc57c\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"6fb4775d-7f8c-48f3-a070-c3cafe3ac2f8\\" id=\\"6fb4775d-7f8c-48f3-a070-c3cafe3ac2f8\\">\uc624\ud508\uc18c\uc2a4\uc5d0\uc11c \uc81c\ud488 \uad00\ub9ac\ud558\ub294 \ubc29\ubc95 \ubc30\uc6b0\uae30</h2><a href=\\"https://blog.mgechev.com/2024/08/25/managing-angular/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.mgechev.com/2024/08/25/managing-angular/</a><p data-notion-block-id=\\"5e9b9b95-ffb0-40f0-9bca-9353ec8be2d7\\">Angular\uc758 PL\ub85c \uc788\uc73c\uba74\uc11c \ubaa9\ud45c \uc124\uc815, \ub370\uc774\ud130 \uc218\uc9d1, \uc758\uc0ac\uacb0\uc815\uc5d0 \ub300\ud574 \uac04\ub2e8\ud558\uac8c \uc124\uba85\ud55c \uae00\uc785\ub2c8\ub2e4. \uac04\ub2e8\ud558\uac8c \uc124\uba85\ud55c \uae00\uc774\ub77c \uc815\uc218\ub97c \ub2f4\uc740 \uae00\uc740 \uc544\ub2c8\uaca0\uc9c0\ub9cc \uc5d4\uc9c0\ub2c8\uc5b4\ub85c\uc11c \uc81c\ud488\uc744 \ub9cc\ub4dc\ub294\ub370 \uc811\uadfc\ud558\ub294 \ubc29\uc2dd\uc744 \ubc30\uc6b8 \uc218 \uc788\ub294 \uc88b\uc740 \uae00\uc774\ub77c \uc0dd\uac01\ud558\uc5ec \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"499c571e-9ae8-43a2-91c4-2db7c80576c6\\" id=\\"499c571e-9ae8-43a2-91c4-2db7c80576c6\\">Svelte\uac00 Signal\ub85c \ubc18\uc751\uc131 \ubb38\uc81c\ub97c \uc5b4\ub5bb\uac8c \ud574\uacb0\ud588\ub294\uac00</h2><a href=\\"https://www.webdevladder.net/blog/svelte-5-signals-fix-its-glitchy-and-inconsistent-reactivity\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.webdevladder.net/blog/svelte-5-signals-fix-its-glitchy-and-inconsistent-reactivity</a><p data-notion-block-id=\\"d3c723d5-f48a-469e-98d1-ddcb97b7f910\\">Svelte 5\uc5d0\uc11c \uc774\uc804\ubd80\ud130 \uc788\ub294 \ubc18\uc751\uc131 \ubb38\uc81c\ub97c Signal\uc744 \ub3c4\uc785\ud568\uc73c\ub85c\uc368 \ud574\uacb0\ud55c \uacfc\uc815\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. Signal\uc740 SolidJS\uc5d0\uc11c \ub3c4\uc785\ub418\uc5b4 Preact, Angular, Svelte\uae4c\uc9c0 \uba54\uc778 \uc0c1\ud0dc\uad00\ub9ac\ub85c \ub3c4\uc785\ub418\uc5c8\uc73c\ubbc0\ub85c \ud55c \ubc88 \uc8fc\ubaa9\ud574\ubcfc\ub9cc \ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"c253f023-7fc8-42d6-900c-ae29c3dc7779\\" id=\\"c253f023-7fc8-42d6-900c-ae29c3dc7779\\">Github \uc6b0\uc2b9!</h2><a href=\\"https://blog.gitbutler.com/why-github-actually-won/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.gitbutler.com/why-github-actually-won/</a><p data-notion-block-id=\\"f9f8afce-a5ac-41a9-8b56-db12ba9d0650\\">Git\uc774 \uc2dc\uc7a5\uc744 \uc9c0\ubc30\ud558\uac8c \ub41c \uc774\uc57c\uae30\uc640, Github\uac00 \uadf8 \uae30\ubc18\uc73c\ub85c \uc9c4\uc9dc\ub85c \ud615\uc0c1\uad00\ub9ac\uc758 \uc9c0\ubc30\uc790\uac00 \ub41c \uc774\uc57c\uae30\ub97c \ud480\uc5b4\ub0b8 \uae00\uc785\ub2c8\ub2e4. \uc6b4\uc774 \ub9ce\uc740 \uac83\uc744 \uc9c0\ubc30\ud55c \uc774\uc57c\uae30\uc9c0\ub9cc, Github\uac00 \ucee4\ubba4\ub2c8\ud2f0\uc5d0 \uc9c4\uc815\uc131 \uc788\ub294 \uc77c\uc6d0\uc774\uc600\ub2e4\ub294 \uac83\uc740 \uc5ec\ub7ec\uac00\uc9c0\ub97c \uc0dd\uac01\ud558\uac8c \ub9cc\ub4dc\ub124\uc694.</p><h2 data-notion-block-id=\\"7a793157-34f5-4be2-8f90-258deb651de8\\" id=\\"7a793157-34f5-4be2-8f90-258deb651de8\\">React \ub370\uc774\ud130 \ubc1b\uc544\uc624\uae30\uc758 \uc5ed\uc0ac</h2><a href=\\"https://reacttraining.com/blog/modern-data-fetching-in-react\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://reacttraining.com/blog/modern-data-fetching-in-react</a><p data-notion-block-id=\\"c06398d5-2e0b-4336-ad4f-b146c5e36b6e\\">\uac00\ubccd\uac8c <code>useEffect</code>\ub97c \ub370\uc774\ud130\ub97c \ubc1b\uc544\uc624\uba74 \uc548\ub418\ub294 \uc774\uc720\uc640 <code>useLoaderData()</code>, RSC\uc5d0 \ub300\ud574 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"92aa7fae-e409-4f7d-a509-9804bc88bc59\\" id=\\"92aa7fae-e409-4f7d-a509-9804bc88bc59\\">RN</h2><a href=\\"https://thisweekinreact.com/newsletter/200#react-native\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://thisweekinreact.com/newsletter/200#react-native</a><p data-notion-block-id=\\"8d4a1ef0-2afe-4268-b330-33c4cc48ebb1\\">RN \ucee8\ud37c\ub7f0\uc2a4\uc758 \uc911\uc694 \ubd80\ubd84\uc744 \uc798 \uc18c\uac1c\ud574\uc11c \ub274\uc2a4\ub808\ud130 \ubd80\ubd84\uc744 \uc9c1\uc811 \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. \ud30c\ud3b8\ud654\ub41c \ub514\ubc84\uae45 \ud234\uc744 \ud06c\ub86c \ub514\ubc84\uae45 \ud234 \uae30\ubc18 \ub514\ubc84\uae45 \ub3c4\uad6c\uc778 \ud4e8\uc988\ubc15\uc2a4\ub85c \ub300\uccb4\ud560 \uac83\uc774\ub77c\ub294 \ubc1c\ud45c\uc640, Static Hermes\uc758 \ud604\uc0c1\ud669\uc744 \uc18c\uac1c\ud558\ub294 \ubc1c\ud45c\ub97c \uc815\ub9ac\ud55c \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"7da759ed-e10c-4e4c-985e-728c4143ffab\\" id=\\"7da759ed-e10c-4e4c-985e-728c4143ffab\\">TypeScript 5.6 \uc18c\uac1c</h2><a href=\\"https://devblogs.microsoft.com/typescript/announcing-typescript-5-6/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://devblogs.microsoft.com/typescript/announcing-typescript-5-6/</a><p data-notion-block-id=\\"188fd76f-764c-411d-af08-8271a9f96ac4\\">\uac00\uc7a5 \uc911\uc2ec\uc774 \ub418\ub294 \uc870\uac74\ubd80 \uad6c\ubb38\uc5d0 \uc2e4\uc218\ub97c \uc904\uc774\ub294 \uc624\ub958\ub97c \uc0c8\ub85c \ubc49\ub3c4\ub85d \ud558\ub294 \uae30\ub2a5\ubd80\ud130 iterator \uc9c0\uc6d0 \uac15\ud654, DX\uac15\ud654 \ub4f1\uc774 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"c4db7f44-6f16-4fa0-8879-d4cc686bbb94\\" id=\\"c4db7f44-6f16-4fa0-8879-d4cc686bbb94\\">\uac04\ub2e8\ud55c \ud301\ub4e4</h2><a href=\\"https://www.nico.fyi/blog/next-js-sequential-tasks-progress-stepper-with-rsc-and-suspense\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.nico.fyi/blog/next-js-sequential-tasks-progress-stepper-with-rsc-and-suspense</a><a href=\\"https://www.smashingmagazine.com/2024/09/sticky-headers-full-height-elements-tricky-combination/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.smashingmagazine.com/2024/09/sticky-headers-full-height-elements-tricky-combination/</a><p data-notion-block-id=\\"100e548d-8a8e-80b1-8caf-e37731365f03\\">\uccab\ubc88\uc9f8\ub294 RSC\uc5d0\uc11c <code>waiting</code> \uc0c1\ud0dc \ud45c\uc2dc\ud558\ub294 \ubc29\ubc95\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc774\uace0, \ub450\ubc88\uc9f8\ub294 <code>position: sticky;</code>\ud5e4\ub354\uc640 \ucd5c\ub300 \ub192\uc774\ub97c \ucc44\uc6b0\ub294 \uc694\uc18c\ub97c CSS\ub85c\ub9cc \ud574\uacb0\ud558\ub294 \ud2b8\ub9ad\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"100e548d-8a8e-802e-8f9c-dbdbc25886ed\\" id=\\"100e548d-8a8e-802e-8f9c-dbdbc25886ed\\"><code>display: contents;</code>\uc124\uba85\ud68c</h2><a href=\\"https://ishadeed.com/article/display-contents/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ishadeed.com/article/display-contents/</a><p data-notion-block-id=\\"d333bb09-4a47-4f19-9bcc-fe012ab3fd90\\">\ud604\uc7ac \uc694\uc18c\ub9cc\uc744(\ud558\uc704 \uc694\uc18c \uc81c\uc678) element tree\uc5d0\uc11c \uc81c\uac70\ud558\ub294 \uae30\ub2a5\uc778 <code>display: contents;</code>\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p>"}')}}]);